def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # For each long vertical 5 rail, repeat the adjacent colored tile from its lower end upward.
    c=max(range(w), key=lambda x:sum(grid[y][x]==5 for y in range(h)))
    rs=[y for y in range(h) if grid[y][c]==5]
    if rs:
        top,bottom=min(rs),max(rs)
        seeds=[y for y in range(bottom+1,min(h,bottom+3)) if any(grid[y][x] not in (0,5) for x in range(c+1,w))]
        if not seeds and any(grid[bottom][x] not in (0,5) for x in range(c+1,w)):
            seeds=[bottom]
        if seeds:
            pats=[[grid[y][x] for x in range(c+1,w)] for y in seeds]
            for y in rs:
                p=pats[(y-bottom-1)%len(pats)] if seeds[0]>bottom else pats[(y-bottom)%len(pats)]
                for x,v in enumerate(p,c+1):
                    if v: out[y][x]=v
    # Horizontal rail: extend colors down its left endpoint across the interior to the next vertical rail.
    for y in range(h):
        cs=[x for x in range(w) if grid[y][x]==5]
        if len(cs)>=2 and cs==list(range(min(cs),max(cs)+1)):
            left,right=min(cs),max(cs)
            # rail has a gap and a continuation at a distant vertical 5 rail; extend to that rail.
            end=right
            for x in range(right+1,w):
                if grid[y][x]==5:
                    end=x-1; break
            for r in range(y+1,h):
                v=grid[r][left]
                if v not in (0,5):
                    for x in range(left+1,end+1): out[r][x]=v
            break
    return out
